        "titolo_orig": "Bolivia, celle a pagamento",
        "testo_it": "Reportage sul sovraffollamento e l'autogestione dei detenuti nel carcere di San Pedro, in Bolivia.",
        "priorita": "Bassa",
        "id_gruppo": 26,
        "link": "https://ilmanifesto.it/bolivia-celle-a-pagamento",
        "orario": "00:06",
